    var presets:[String]{switch self{
    case .kick:return ["Four on the floor","Every 8 steps","Boom Bap","2-Step Garage","Broken Beat","Euclidean 5/16","Trap Kick","Random"]
    case .snare:return ["Backbeat 2 & 4","Half-time","Ghost Notes","Breakbeat","Jungle","Syncopated Clap","Snare Roll","Random"]
    case .hat:return ["8th Notes","16th Notes","Offbeat","Swung Hats","Trap 1/32 Rolls","Trap Triplets","Trap 1/64 Rolls","Broken Hats","Random"]
    case .bass:return ["Root Pulse","Syncopated","Walking Bass","Octave Groove","808 Sparse","Arpeggiated","Ostinato","Random"]
    case .lead:return ["Motif","Question / Answer","Arpeggio","Ascending / Descending","Sparse Melody","Syncopated Lead","Pentatonic Phrase","Random"]
    case .chords:return ["Triads","Cinematic 7ths","Jazz 9ths","Offbeat Stabs","Gospel Voicings","Broken Chords","Long Pads","Random"]}}
}
